-- Stable progress keys (docs/learning-experience §7.4).
--
-- Saved lesson progress used to name positions: a skill-check stage was `<lesson>:quiz-N`, and the
-- explainer remembered `stepIndex`. Inserting an opener, an explain step or a fourth check moves
-- every position after it, so a learner would resume on the wrong screen. Stages are now named by
-- the question they ask (`<lesson>:check:<questionId>`) and steps by their authored id.
--
-- The rows below are the lesson structure as it stood when this migration was written, taken
-- from every content/*/bundle.json on 6 October 2026. Mapping saved positions through that
-- snapshot, rather than through whatever content is loaded later, keeps the translation correct
-- even when a lesson is rewritten in the same release. Positions with no entry (a lesson created
-- later, an index past the end) are left as they are: the player clamps them, as before.
CREATE TEMP TABLE legacy_check_stage (journey_id TEXT NOT NULL, old_stage TEXT NOT NULL, new_stage TEXT NOT NULL);
CREATE TEMP TABLE legacy_step_position (journey_id TEXT NOT NULL, stage_id TEXT NOT NULL, step_index INTEGER NOT NULL, step_id TEXT NOT NULL);
CREATE INDEX temp.legacy_check_stage_key ON legacy_check_stage (journey_id, old_stage);
CREATE INDEX temp.legacy_step_position_key ON legacy_step_position (journey_id, stage_id, step_index);

-- Skill-check stages: copy each saved row to its question-named id, then drop the positional one.
INSERT OR IGNORE INTO journey_progress (user_id, journey_id, stage_id, state, interaction_state, updated_at)
  SELECT p.user_id, p.journey_id, k.new_stage, p.state, p.interaction_state, p.updated_at
  FROM journey_progress p
  JOIN legacy_check_stage k ON k.journey_id = p.journey_id AND k.old_stage = p.stage_id;
DELETE FROM journey_progress
  WHERE EXISTS (
    SELECT 1 FROM legacy_check_stage k
    WHERE k.journey_id = journey_progress.journey_id AND k.old_stage = journey_progress.stage_id
  );

-- The once-only XP for finishing a stage is keyed by stage id; rename it so a replay of the same
-- check after the rename is still recognised as already rewarded.
UPDATE OR IGNORE learning_events
  SET event_key = 'stage:' || reference_id || ':' || (
    SELECT k.new_stage FROM legacy_check_stage k
    WHERE k.journey_id = learning_events.reference_id
      AND learning_events.event_key = 'stage:' || k.journey_id || ':' || k.old_stage
  )
  WHERE kind = 'stage' AND EXISTS (
    SELECT 1 FROM legacy_check_stage k
    WHERE k.journey_id = learning_events.reference_id
      AND learning_events.event_key = 'stage:' || k.journey_id || ':' || k.old_stage
  );

-- Explainer position: record the step id beside the index the row already holds.
UPDATE journey_progress
  SET interaction_state = json_set(interaction_state, '$.stepId', (
    SELECT k.step_id FROM legacy_step_position k
    WHERE k.journey_id = journey_progress.journey_id
      AND k.stage_id = journey_progress.stage_id
      AND k.step_index = json_extract(journey_progress.interaction_state, '$.stepIndex')
  ))
  WHERE json_valid(interaction_state)
    AND json_type(interaction_state, '$.stepIndex') = 'integer'
    AND json_type(interaction_state, '$.stepId') IS NULL
    AND EXISTS (
      SELECT 1 FROM legacy_step_position k
      WHERE k.journey_id = journey_progress.journey_id
        AND k.stage_id = journey_progress.stage_id
        AND k.step_index = json_extract(journey_progress.interaction_state, '$.stepIndex')
    );

DROP TABLE legacy_check_stage;
DROP TABLE legacy_step_position;
